  // screenText in [onHit] would re-sample mid-render (gh-1049).
  var hit = '';
  return pollUntil(
    matched: () {
      hit = screenText;
      return hit.contains(pattern);
    },
    onHit: () => hit,
    screenText: () => screenText,
    rawTail: _rawTail,
    what: '"$pattern" on screen',
